tags.expression:
// True when OPC server is connected AND
// (we're actively measuring (recent status change) OR the heartbeat updated recently)

{[System]Gateway/OPC/Connections/XsperGo Opc Ua Server/Connected}
&&
(
    (
        {[.]../LM/Control/Status} = "Measuring"
        && secondsBetween(timestampOf({[.]../LM/Control/Status}), now(1000)) < 120
    )
    ||
    (
        secondsBetween(timestampOf({[.]../LM/Control/Heartbeat}), now(1000)) < 10
    )
)

eventScripts.script:
logger = system.util.getLogger("PAT.EM.Tags")
logger.debug("Reset command for %s recieved" % tagPath)

if not initialChange and currentValue.getValue():
	try:
		chart_id = system.tag.readBlocking(["[.]Val_ChartID"])[0].value
		if chart_id:
			system.sfc.cancelChart(chart_id)
	except Exception as e:
		logger.debug("error canceling chart - " + str(e))
	finally:
		system.tag.writeBlocking([tagPath], [0])
